// ============ 日本語文分割(自動対応段落用) ============
function splitJP(text){
let parts=[], buf='', depth=0;
for(const ch of text){
buf+=ch;
if(ch==='「') depth++;
if(ch==='」') depth--;
if((ch==='。'||ch==='？'||ch==='！') && depth===0){ parts.push(buf.trim()); buf=''; }
}
if(buf.trim()) parts.push(buf.trim());
return parts;
}

// ============ PARAGRAPHS 構築 ============
const ART_LABEL={'8':'第八回',' 9':'第九回','9':'第九回','10':'第十回','11':'第十一回','12':'第十二回','13a':'第十三回A：SpaceX指数採用','13b':'第十三回B：目標株価'};
function artKeyOf(p){
if(p.s!==13) return String(p.s);
return p.art==='SpaceX Nasdaq採用' ? '13a' : '13b';
}
const PARAS = PARAS_RAW.map((p,i)=>{
let sentences;
if(SENT_OVERRIDE[i]){
sentences = SENT_OVERRIDE[i];
} else {
const enS = splitSentences(p.en);
const jpS = splitJP(p.jp);
sentences = enS.map((s,idx)=>({en:s, jp: jpS.length===enS.length ? jpS[idx] : p.jp}));
}
return { id:'P'+i, idx:i, s:p.s, art:p.art||null, artKey:artKeyOf(p), en:p.en, jp:p.jp, sentences };
});

